/**
 * Shared Zod primitives.
 *
 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
 * on the server. Keep them free of server-only imports.
 */

const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/** Builds a branded-id schema whose output type is the branded alias. */
function brandedId<T extends string>(label: string) {
  return z
    .string()
    .regex(ULID, `${label} must be a ULID`)
    .transform((value) => value as T);
}

export const userIdSchema = brandedId<UserId>("userId");
export const orgIdSchema = brandedId<OrgId>("orgId");
export const projectIdSchema = brandedId<ProjectId>("projectId");
export const issueIdSchema = brandedId<IssueId>("issueId");
export const commentIdSchema = brandedId<CommentId>("commentId");
export const memberIdSchema = brandedId<MemberId>("memberId");
export const notificationIdSchema = brandedId<NotificationId>("notificationId");
export const activityIdSchema = brandedId<ActivityId>("activityId");
export const invitationIdSchema = brandedId<InvitationId>("invitationId");
export const labelIdSchema = brandedId<LabelId>("labelId");
export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
export const webhookIdSchema = brandedId<WebhookId>("webhookId");

export const isoTimestampSchema = z
  .iso
  .datetime()
  .transform((value) => value as IsoTimestamp);

export const emailSchema = z.email().max(254).toLowerCase();

export const sortDirectionSchema = z.enum(["asc", "desc"]);

export const pageRequestSchema = z.object({
  limit: z.number().int().min(1).max(100).default(25),
  cursor: z.string().nullable().optional(),
});

export const archiveScopeSchema = z.object({
  includeArchived: z.boolean().optional(),
});

export const hexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");

export type PageRequestInput = z.infer<typeof pageRequestSchema>;
export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;
"use server";

/**
 * Updates project metadata.
 *
 * Owner D. Visibility is part of this payload, which is why the permission
 * resource carries the *incoming* visibility: raising a project to `public`
 * must be judged against what it is becoming, not what it was.
 *
 * Must call (do not reimplement): updateProjectSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateProjectSchema, type UpdateProjectInput } from "@/schemas/project";
import { updateProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof updateProjectSchema, Project>(
  updateProjectSchema,
  async (raw, actor) => {
    const input = raw as UpdateProjectInput;

    const allowed = can(actor, "project:update", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: input.visibility ?? "org",
      leadId: input.leadId ?? actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:update");
    }

    const project = await updateProject(actor, input);
    revalidateTagged([projectTag(project.id)], CACHE_PROFILES.minutes);
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function updateProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use client";

/**
 * Editor for name, description, visibility, status, lead and colour.
 *
 * Owner D. Private to the project settings route. `updateProjectSchema` makes
 * every field optional, so the form sends the whole set and lets the service
 * diff them — which is also what produces `changedFields` on the event.
 */

import { useActionState } from "react";
import { fieldErrorsFromZod } from "@/lib/errors";
import { updateProjectSchema } from "@/schemas/project";
import type { ActionResult } from "@/types/api";
import type { OrgId, UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { Project } from "@/types/project";

export type ProjectSettingsFormProps = {
  orgId: OrgId;
  project: Project;
  members: readonly MemberWithUser[];
  onSubmit: (input: unknown) => Promise<ActionResult<Project>>;
};

type SettingsState = ActionResult<Project> | null;

export function ProjectSettingsForm(props: ProjectSettingsFormProps) {
  const { orgId, project, members, onSubmit } = props;

  const [state, submit, pending] = useActionState<SettingsState, FormData>(
    async (_previous, formData) => {
      const leadId = String(formData.get("leadId") ?? "");
      const description = String(formData.get("description") ?? "").trim();

      const parsed = updateProjectSchema.safeParse({
        orgId,
        projectId: project.id,
        name: String(formData.get("name") ?? ""),
        description: description.length === 0 ? null : description,
        visibility: String(formData.get("visibility") ?? project.visibility),
        status: String(formData.get("status") ?? project.status),
        color: String(formData.get("color") ?? project.color),
        leadId: leadId.length === 0 ? null : (leadId as UserId),
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the fields below.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return onSubmit(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <form action={submit} className="space-y-5">
      {state?.ok === true ? (
        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
          Project updated.
        </p>
      ) : null}

      <div className="space-y-1">
        <label htmlFor="name" className="text-sm font-medium">
          Name
        </label>
        <input
          id="name"
          name="name"
          defaultValue={project.name}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
        {fieldErrors.name !== undefined ? (
          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
        ) : null}
      </div>

      <div className="space-y-1">
        <label htmlFor="description" className="text-sm font-medium">
          Description
        </label>
        <textarea
          id="description"
          name="description"
          rows={4}
          defaultValue={project.description ?? ""}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="visibility" className="text-sm font-medium">
            Visibility
          </label>
          <select
            id="visibility"
            name="visibility"
            defaultValue={project.visibility}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="private">Private — people on the project</option>
            <option value="org">Organization — everybody here</option>
            <option value="public">Public — anybody with the link</option>
          </select>
        </div>

        <div className="space-y-1">
          <label htmlFor="status" className="text-sm font-medium">
            Status
          </label>
          <select
            id="status"
            name="status"
            defaultValue={project.status}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="active">Active</option>
            <option value="paused">Paused</option>
            <option value="completed">Completed</option>
          </select>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="leadId" className="text-sm font-medium">
            Lead
          </label>
          <select
            id="leadId"
            name="leadId"
            defaultValue={project.leadId ?? ""}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="">No lead</option>
            {members.map((member) => (
              <option key={member.id} value={member.userId}>
                {member.user.name}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-1">
          <label htmlFor="color" className="text-sm font-medium">
            Colour
          </label>
          <input
            id="color"
            name="color"
            type="color"
            defaultValue={project.color}
            className="h-9 w-16 rounded border border-slate-300"
          />
        </div>
      </div>

      <button
        type="submit"
        disabled={pending}
        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save project"}
      </button>
    </form>
  );
}

/**
 * Project settings including archive.
 *
 * Owner D. Editing needs `project:update`; archiving needs `project:archive`,
 * which sits higher in `ROLE_MATRIX` — so the archive block is gated
 * separately rather than assumed from the first check.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { archiveProjectAction } from "@/actions/projects/archive-project";
import { updateProjectAction } from "@/actions/projects/update-project";
import { can } from "@/lib/permissions";
import { listMembers } from "@/server/services/member-service";
import { loadProjectContext } from "../../../_lib/project-context";
import { ArchiveProjectPanel } from "./archive-project-panel";
import { ProjectSettingsForm } from "./project-settings-form";

type PageParams = { orgSlug: string; projectSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Project settings",
};

const MEMBER_PICKER_LIMIT = 100;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug } = await props.params;
  await props.searchParams;

  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);

  const resource = {
    kind: "project",
    orgId: org.id,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  } as const;

  if (!can(actor, "project:update", resource)) {
    notFound();
  }
  const mayArchive = can(actor, "project:archive", resource);

  const members = await listMembers(actor, {
    orgId: org.id,
    limit: MEMBER_PICKER_LIMIT,
  });

  return (
    <div className="max-w-xl space-y-10">
      <section className="space-y-6">
        <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
          Project details
        </h2>
        <ProjectSettingsForm
          orgId={org.id}
          project={project}
          members={members.items}
          onSubmit={updateProjectAction}
        />
      </section>

      {mayArchive ? (
        <section className="rounded-md border border-amber-200 bg-amber-50 p-6">
          <h2 className="text-sm font-semibold text-amber-900">
            Archive this project
          </h2>
          <p className="mt-2 text-sm text-amber-800">
            Archiving hides the project and, by default, its issues. Nothing is
            deleted — an owner can restore it from the project list.
          </p>

          <div className="mt-4">
            <ArchiveProjectPanel
              project={project}
              actor={actor}
              onConfirm={archiveProjectAction}
            />
          </div>
        </section>
      ) : null}
    </div>
  );
}
